(function(){
'use strict';
const D=CatData,E=CatEngine,C=CatContent,$=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
let state=null,selected=null,storageOK=true,lastAction=null,flash={};
let activeMetaKey='catcity-meta';function loadMeta(){try{return JSON.parse(localStorage.getItem(activeMetaKey)||'{"achievements":[],"cats":[]}')}catch{return {achievements:[],cats:[]};}}
let meta=loadMeta();meta.gallery=Array.isArray(meta.gallery)?meta.gallery:[];
function saveMeta(){try{localStorage.setItem('catcity-meta',JSON.stringify(meta));}catch{}}
function rememberProgress(){const a=E.achievements(state).filter(x=>x.unlocked).map(x=>x.id);meta.achievements=[...new Set([...meta.achievements,...a])];const seen=state.history.filter(h=>h.event).flatMap(h=>D.events.find(e=>e.id===h.event)?.catIds||[]);meta.cats=[...new Set([...meta.cats,...seen])];for(const c of catsForState()){const v=state.cats[c.id];if(meta.cats.includes(c.id)){meta.gallery.push(`${c.id}:base`);if(v.trust>=50||v.health>=70)meta.gallery.push(`${c.id}:growth`);if(v.trust>=75||state.flags.includes('heiSecret')&&c.id==='hei'||state.flags.includes('yueSecret')&&c.id==='yue')meta.gallery.push(`${c.id}:special`);}}const rewardMap={'first-letter':['hei:base','tang:base','juan:base','hu:base','yu:base','yue:base'],'hei-trust':['hei:growth'],'owner-found':['tang:growth','tang:special'],'pair-care':['juan:growth','yu:growth'],'quiet-moon':['yue:growth'],'medical-handoff':['hu:growth'],'midnight-letter':['hei:special'],'moonlit-visitor':['yue:special'],'atlas-stamp':['tang:special','juan:special'],'atlas-graduate':['tang:growth','tang:special'],'archive-legacy':['juan:special','yue:special'],'pku-route':['hei:special','tang:special','juan:special','hu:special','yu:special','yue:special']};for(const a of E.achievements(state).filter(x=>x.unlocked))for(const key of (rewardMap[a.id]||[]))meta.gallery.push(key);meta.gallery=[...new Set(meta.gallery)];saveMeta();}
function viewedAchievements(){const current=E.achievements(state);return current.map(a=>({...a,unlocked:a.unlocked||meta.achievements.includes(a.id)}));}
const labels={health:'健康',trust:'信任',stress:'压力'};const packForState=()=>state?.variant==='pku'&&D.pkuPack?D.pkuPack:D;const catsForState=()=>E.catList(state);const eventView=e=>{const x=packForState().eventCopy?.[e.id];return x?{...e,...x}:e};
const fmt=n=>n>0?'+'+n:String(n);
function save(){try{localStorage.setItem('catcity-save',JSON.stringify(state));}catch{storageOK=false;}}
function load(){try{const s=JSON.parse(localStorage.getItem('catcity-save'));return E.validate(s)?s:null;}catch{storageOK=false;return null;}}
function delta(r){return Object.entries(r).map(([k,v])=>`${D.resourceLabels[k]} ${fmt(v)}`).join(' · ');}
function changes(o){return Object.entries(o.changes||{}).map(([id,r])=>catsForState().find(c=>c.id===id).name+'：'+Object.entries(r).map(([k,v])=>`${labels[k]} ${fmt(v)}`).join('、')).join('；')||'猫咪状态不直接变化';}
let music=null;let musicOn=localStorage.getItem('catcity-music')!=='off';
function toggleMusic(){musicOn=!musicOn;localStorage.setItem('catcity-music',musicOn?'on':'off');if(musicOn)startMusic();else stopMusic();render();toast(musicOn?'BGM 已打开':'BGM 已关闭');}
function startMusic(){if(music||!musicOn)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const ctx=new A();const gain=ctx.createGain();gain.gain.value=.035;gain.connect(ctx.destination);const notes=[261.63,329.63,392,523.25,392,329.63];let i=0;const tick=()=>{if(!musicOn){stopMusic();return}const o=ctx.createOscillator();o.type='sine';o.frequency.value=notes[i++%notes.length];o.connect(gain);o.start();o.stop(ctx.currentTime+.65);music.timer=setTimeout(tick,900)};music={ctx,gain,timer:null};tick();}catch{}}
function stopMusic(){if(!music)return;clearTimeout(music.timer);music.ctx.close().catch(()=>{});music=null;}
function header(){return `<header class="mast"><div class="brand"><div class="seal">🐾</div><div><h1>猫城来信</h1><div class="subtitle">${state.variant==='pku'?'燕园猫协版 · 未名湖边的每一次选择':'七日救助手记 · 每一次选择，都有回声'}</div></div></div><div class="daybox"><button class="music-toggle" data-action="music">${musicOn?"♫ BGM":"♪ 静音"}</button><b>WEEK ${state.week} · DAY ${state.day} / 7</b><span>${D.dayNames[state.day-1]} · ${state.mode==="demo"?"演示路线":(E.boons[state.boon]?.name||"完整路线")}</span></div></header>`;}
function resources(){const icons={money:'¥',food:'◌',medical:'✚',ap:'◷'};const keys=['money','food','medical','ap'];const support=Math.round((state.resources.community+state.resources.volunteer)/2);return keys.map(k=>{const v=D.resourceLabels[k],d=flash.resources?.[k]||0;return `<div class="resource ${d?'resource-flash':''}"><span class="icon">${icons[k]}</span><div>${v}</div><strong>${state.resources[k]}${d?` <em class="delta-mark ${d>0?'up':'down'}">${d>0?'↑':'↓'}${Math.abs(d)}</em>`:''}</strong></div>`}).join('')+`<div class="resource support-resource"><span class="icon">⌂</span><div>社区支持</div><strong>${support}</strong><small>居民 ${state.resources.community} · 志愿 ${state.resources.volunteer}</small></div>`;}
function portrait(c,variant='base'){const prefix=state?.variant==='pku'?'pku-':'';const file=['hei','tang','juan','hu','yu','yue'].includes(c.id)?`猫咪头像/${prefix}${c.id}${variant==='growth'&&state?.variant!=='pku'?'-growth':''}.png`:'';if(file)return `<img class="portrait ink-portrait" src="${file}" alt="${c.name}" loading="lazy">`;return `<svg class="portrait" viewBox="0 0 80 80" aria-hidden="true"><circle cx="40" cy="40" r="39" fill="#eee9db"/><path d="M17 42 16 14 34 26Q40 23 47 26L65 14 63 44Q68 66 40 69Q12 66 17 42" fill="${c.color}"/><path d="M20 20 29 28 21 34M60 20 51 28 60 34" fill="#d8b6a0"/><circle cx="29" cy="43" r="3" fill="#243630"/><circle cx="51" cy="43" r="3" fill="#243630"/></svg>`;}
function sidebar(){const got=viewedAchievements().filter(a=>a.unlocked).length,total=E.achievementDefs.length;return `<aside class="side"><h2>站内资源</h2>${resources()}<p class="tiny">核心资源只有资金、猫粮、医疗名额和行动点。社区与志愿者合并显示为“社区支持”，材料进入收集进度。</p><button class="collection-button" data-action="codex">📖 图鉴与成就 <b>${got}/${total}</b><small>每个选择都会留下可收集的记录</small></button><div class="cat-list"><h2>猫咪图鉴 · 点击读档案</h2>${catsForState().map(c=>`<button class="cat" data-cat="${c.id}">${portrait(c)}<span><b>${c.name}</b><small>${c.tag}</small><small>健康 ${state.cats[c.id].health} · 信任 ${state.cats[c.id].trust} · 压力 ${state.cats[c.id].stress}</small></span></button>`).join('')}</div></aside>`;}
function board(){const c=state.resources.community,v=state.resources.volunteer;const note=c>=65?'“最近的轮班表很清楚，食盆也收得及时。我们愿意继续观察。”':c>=45?'“我理解你们在努力，但请把投喂时间和清洁安排写清楚。”':'“公告栏上的投诉还没有解决。请先说明谁负责明天的清理。”';const help=v>=65?'志愿者意愿高：明天可获得 4 个行动点。':v>=40?'志愿者正在观望：保持稳定交接可以增加支持。':'志愿者意愿偏低：不要把所有照护都留给下一班。';return `<div class="field-notes"><section class="notice-board"><h3>公告栏 · 社区声音</h3><p>${note}</p><small>社区信任 ${c} / 100</small></section><section class="notice-board"><h3>今日交接目标</h3><p>${E.available(state).length?E.available(state).map(e=>{const q=eventView(e);return `${q.place}：${q.title}`}).join('<br>'):'今天的来信已经处理完。'}</p><small>${help}</small></section><section class="notice-board goal-card ${dailyGoal().done?"goal-done":""}"><h3>今日小目标 ${dailyGoal().done?"✓":""}</h3><p>${dailyGoal().done?"已完成：":""}${dailyGoal().text}</p><small>${dailyGoal().done?"目标完成，照护记录已加盖印章。":"完成目标会提高图鉴进度，并可能触发隐藏路线。"}</small></section></div>`;}
function dailyGoal(){const goals=[['first','先完成一封来信'],['calm','让任意一只猫的压力下降'],['health','让任意一只猫的健康上升'],['trust','让任意一只猫的信任上升'],['support','让社区或志愿者支持增加'],['pair','处理一次涉及两只猫的来信'],['handoff','留下一个可交接的安排']];const g=goals[(state.day-1+(state.week-1)*2)%goals.length];const rows=state.history.filter(h=>h.event&&h.day===state.day);let done=false;if(g[0]==='first')done=rows.length>0;if(g[0]==='calm')done=rows.some(h=>Object.values(h.changes||{}).some(x=>(x.stress||0)<0));if(g[0]==='health')done=rows.some(h=>Object.values(h.changes||{}).some(x=>(x.health||0)>0));if(g[0]==='trust')done=rows.some(h=>Object.values(h.changes||{}).some(x=>(x.trust||0)>0));if(g[0]==='support')done=rows.some(h=>Object.entries(h.resources||{}).some(([k,v])=>['community','volunteer'].includes(k)&&v>0));if(g[0]==='pair')done=rows.some(h=>(D.events.find(e=>e.id===h.event)?.catIds.length||0)>=2);if(g[0]==='handoff')done=rows.some(h=>(h.flags||[]).some(f=>['communityPlan','nextMentor','heiPromise','careTeam'].includes(f)));return {id:g[0],text:g[1],done};}
function sound(kind){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const ctx=music?.ctx||new A();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=kind==='achievement'?784:kind==='goal'?659:440;g.gain.setValueAtTime(.0001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(kind==='achievement'?.08:.035,ctx.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.22);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.24);if(!music)ctx.close();}catch{}}

function map(){const normalPlaces=[['宿舍后巷',20,26],['旧校门',15,76],['银杏庭院',49,46],['校医院旁',78,24],['图书馆侧门',79,76],['公告栏',47,85]];const pkuPlaces=packForState().mapSpots||[];const places=state.variant==='pku'?pkuPlaces:normalPlaces;const spots=catsForState().map((c,i)=>[c.id,c.name,(state.variant==='pku'?(pkuPlaces[i%pkuPlaces.length]?.[1]||20):[20,15,47,78,79,60][i]),(state.variant==='pku'?(pkuPlaces[i%pkuPlaces.length]?.[2]+10||38):[38,88,38,36,88,58][i])]);return `<section class="campus"><div class="map-caption"><b>校园遇见地图</b><span>先选一只猫，再读它此刻的来信 · 可重复查看档案</span></div><div class="map-board"><svg viewBox="0 0 800 240" preserveAspectRatio="none" aria-hidden="true"><rect width="800" height="240" fill="#e8edde"/><path d="M0 120Q200 80 400 130T800 110M120 0Q250 120 110 240M600 0Q500 120 650 240" stroke="#faf8ed" stroke-width="24" fill="none"/><ellipse cx="410" cy="78" rx="58" ry="35" fill="#c6d7bf"/><ellipse cx="300" cy="178" rx="50" ry="24" fill="#c6d7bf"/><path d="M355 60h110v33H355z" fill="#b8cdb0"/></svg>${places.map(([p,x,y])=>{const ev=E.available(state).filter(e=>eventView(e).place===p);return `<button style="left:${x}%;top:${y}%" class="map-pin ${selected&&eventView(D.events.find(e=>e.id===selected)||{}).place===p?'active':''}" ${ev.length?'':'disabled'} data-event="${ev[0]?.id||''}">${esc(p)}<small>${ev.length?ev.length+' 封待读':'今日暂无来信'}</small></button>`;}).join('')}${spots.map(([id,name,x,y])=>{const c=catsForState().find(c=>c.id===id),ev=E.available(state).find(e=>e.catIds.includes(id));return `<button title="${name}" aria-label="遇见${name}" data-cat="${id}" data-event="${ev?.id||''}" class="cat-marker ${ev?'has-letter':''}" style="left:${x}%;top:${y}%"><span>${portrait(c)}</span><b>${name}</b>${ev?'<i>新</i>':''}</button>`;}).join('')}</div></section>`;}
function render(){if(!state){$('#app').innerHTML=`<div class="start"><div class="startcard"><div class="seal">🐾</div><h1>猫城来信</h1><p class="subtitle">七日救助手记 · 单机叙事 Demo</p><p class="lead">交接本上有六个名字，账上有 880 元，合作诊所留了两个名额。七天里，你要决定先去哪里，又愿意为谁多等一会儿。</p><div class="rule"><div><b>看见</b><br>六只猫不是六个数值，而是六段具体关系</div><div><b>选择</b><br>信任、健康、压力和社区态度互相牵动</div><div><b>留下</b><br>结局写给下一班，不把公益做成一次性通关</div></div><p class="tiny">这是虚构的公益叙事体验，数值是玩法抽象。本版居民反馈与规则解读为本地预写内容，未接入在线 AI。无需登录或联网。</p><div class="boon-title">选择故事版本</div><div class="boon-grid variant-grid"><button class="boon-card variant-card selected" data-action="begin" data-variant="default"><b>猫城原版</b><small>六只校园流浪猫</small><p>沿用当前熟悉的救助站故事。</p></button><button class="boon-card variant-card pku-card" data-action="begin" data-variant="pku"><b>燕园猫协版</b><small>未名湖边的公开资料再创作</small><p>学术猫、畅蠢、小菊、四月、博雅耳朵与湖心月，故事从北大校园地图开始。</p></button></div><div class="boon-title">先选本周的救助站策略 · 每局可以换一种玩法</div><div class="boon-grid">${Object.entries(E.boons).map(([id,b])=>`<button class="boon-card" data-action="begin" data-boon="${id}" data-variant="default"><b>${b.name}</b><small>${b.tag}</small><p>${b.desc}</p></button>`).join('')}</div><div class="feature-preview"><div><b>♫ 氛围 BGM</b><small>点击右上角可随时开关</small></div><div><b>◆ 每日小目标</b><small>每天都有一件值得完成的事</small></div><div><b>▣ 周报分享</b><small>每周结束生成可截图的猫城周报</small></div></div><div class="start-actions"><button class="ghost" data-action="music">${musicOn?"♫ 打开 BGM":"♪ BGM 已静音"}</button><button class="ghost" data-action="demo">进入 3 分钟演示模式</button></div></div></div>`;return;}
 if(state.ended){renderEnd();return;}
 const available=E.available(state);if(!available.some(e=>e.id===selected))selected=available[0]?.id||null;
 const e=available.find(e=>e.id===selected),day=C.days[state.day-1];
 $('#app').innerHTML=`<div class="shell">${header()}<div class="layout">${sidebar()}<main class="main"><div class="daily"><small>第 ${state.day} 天 · ${day[0]}</small><p>${day[1]}</p></div>${map()}${board()}<nav class="event-tabs" aria-label="今日来信">${available.map(v=>{const q=eventView(v);return `<button class="ghost ${v.id===selected?'selected':''}" data-event="${v.id}" aria-pressed="${v.id===selected}">${q.title}</button>`}).join('')}</nav>${e?eventHtml(e):'<article class="letter day-complete"><div class="place">今日交接</div><h2>今天的信都读完了</h2><p class="body">把记录留下，再去迎接下一天。剩余行动点不会累积。</p></article>'}<div class="bottom"><button class="ghost" data-action="journal">完整手记</button><button class="ghost" data-action="tutorial">新手指引</button><button class="ghost" data-action="share">分享给朋友</button>${state.day===1&&state.history.length===0?`<button class="ghost" data-action="demo">切换 3 分钟演示</button>`:``}<button class="primary" data-action="night">${state.day===7?'完成七日交接':'结束今天'} →</button></div>${logHtml()}<div class="bottom"><button class="ghost" data-action="reset">重新开始</button><span class="tiny">${storageOK?'选择自动保存 · 刷新可继续':'浏览器无法保存 · 当前可继续玩，关闭后进度会丢失'}</span></div></main></div></div>`;
}
function eventHtml(e){const v=eventView(e),context=C.context(state,e.id),blocked=e.options.every(o=>E.reason(state,o));return `<article class="letter"><div class="place">${v.place} · ${e.id}</div><h2>${v.title}</h2><div class="encounter-strip">${e.catIds.map(id=>{const c=catsForState().find(c=>c.id===id);return `<span>${portrait(c)}<b>${c.name}</b></span>`}).join()}</div><p class="body">${v.body}</p>${context?`<div class="continuity"><b>来自前几页的回声</b><p>${esc(context)}</p></div>`:''}<div class="hint">${blocked?'当前资源不足以执行这里的选项。可切换今日其他来信，或结束今天，把未处理事件记入交接。':'选择之前，可以展开查看每种行动的具体影响。'}</div><div class="options">${e.options.map(o=>{const why=E.reason(state,o);return `<button class="option" data-option="${o.id}" ${why?'disabled':''}><b>${o.label}</b><p>${o.desc}</p><span class="delta">${delta(o.resources)}${why?' · '+why:''}</span></button>`;}).join('')}</div><details class="explanation"><summary>查看取舍 · 本地规则解读</summary>${e.options.map(o=>`<div class="explain-row"><b>${o.label}</b><p>${changes(o)}</p></div>`).join('')}<small>直接读取固定规则；不是实时 AI 输出。数值会限制在 0—100。</small></details></article>`;}
function historyHtml(rows){return rows.map(h=>h.type==='week'?`<div class="logrow"><span>第 ${h.to} 周开始</span><b>带着 ${h.materials} 份材料继续</b></div>`:h.type==='night'?`<div class="logrow"><span>第 ${h.day} 天 · 夜间交接</span><b>${h.skipped.length?'未处理 '+h.skipped.length+' 件':'当天来信已全部处理'}</b>${h.skipped.length?`<small>${h.skipped.map(id=>eventView(D.events.find(e=>e.id===id)).title).join('、')}</small>`:''}</div>`:`<div class="logrow"><span>第 ${h.day} 天 · ${esc(h.title)}</span><b>${esc(h.label)}</b><small>${esc(h.feedback)}<br>${delta(h.resources)}<br>${changes(h)}</small></div>`).join('');}
function logHtml(){return `<section class="log"><h3>最近四条记录 · 累计处理 ${state.done.length} 件</h3>${historyHtml(state.history.slice(-4).reverse())||'<p class="tiny">第一条记录从你的选择开始。</p>'}</section>`;}
function modal(title,body,buttons){const prior=document.activeElement;const el=document.createElement('dialog');el.className='reading';el.innerHTML=`<div class="modal-card"><h2>${title}</h2>${body}<div class="dialog-actions">${buttons}</div></div>`;el.addEventListener('close',()=>{el.remove();if(prior?.isConnected)prior.focus();});document.body.append(el);el.showModal();return el;}
function galleryKeys(c){const v=state.cats[c.id],keys=[];if(meta.gallery.includes(`${c.id}:base`)||state.history.some(h=>h.event&&D.events.find(e=>e.id===h.event)?.catIds.includes(c.id)))keys.push('base');if(meta.gallery.includes(`${c.id}:growth`)||(v.trust>=50||v.health>=70))keys.push('growth');if(meta.gallery.includes(`${c.id}:special`)||(v.trust>=75||state.flags.includes('heiSecret')&&c.id==='hei'||state.flags.includes('yueSecret')&&c.id==='yue'))keys.push('special');return keys;}
function growth(c,v){const score=Math.round((v.health+v.trust+(100-v.stress))/3);return score>=78?['相互信任',score]:score>=58?['开始熟悉',score]:score>=38?['观察期',score]:['需要耐心',score];}function galleryMedia(c,kind){if(state.variant==='pku'&&kind==='special')return `<div class=\"archive-reward\"><b>燕园猫协</b><strong>关系档案卡</strong><small>${c.name} · 已解锁</small><i>把名字、关系与下一次回访交给下一班</i></div>`;return `<img src=\"猫咪头像/${state.variant==='pku'?'pku-':''}${c.id}${kind==='growth'&&state.variant!=='pku'?'-growth':''}.png\" alt=\"${c.name} ${kind}\">`; }
function codex(){const ach=viewedAchievements(),done=ach.filter(a=>a.unlocked).length;const cards=catsForState().map(c=>{const seen=meta.cats.includes(c.id)||state.history.some(h=>h.event&&D.events.find(e=>e.id===h.event)?.catIds.includes(c.id));const v=state.cats[c.id],g=growth(c,v);return `<button class="codex-cat ${seen?'seen':''}" data-cat="${c.id}">${seen?portrait(c):'<span class="locked-cat">?</span>'}<div class="codex-cat-copy"><b>${seen?c.name:'未发现的猫咪'}</b><small>${seen?c.theme:'在地图上寻找新的脚印'}</small>${seen?`<em>${g[0]} · 信任 ${v.trust} · 健康 ${v.health}</em><i class="growth-bar"><span style="width:${g[1]}%"></span></i>`:'<em>待解锁</em>'}</div></button>`}).join('');const badges=ach.map(a=>`<div class="badge ${a.unlocked?'unlocked':''}"><span>${a.unlocked?a.icon:'？'}</span><div><b>${a.name}</b><small>${a.desc}</small></div>${a.unlocked?'<i>已达成</i>':''}</div>`).join('');modal('猫咪图鉴与成就',`<div class="codex-summary"><b>${done}/${ach.length}</b><span>已完成的收集目标</span><i>本机收藏 ${meta.cats.length} 只猫 · 材料 ${state.resources.materials} · 已处理 ${state.history.filter(h=>h.event).length} 个节点</i></div><div class="codex-tabs"><b>猫咪图鉴</b><span>养成阶段会随选择变化</span></div><div class="codex-grid">${cards}</div><div class="codex-tabs"><b>成就册</b><span>把每次选择变成长期目标</span></div><div class="badge-grid">${badges}</div>`,'<button class="primary" data-action="close">合上图鉴</button>');}
function showCat(id){const c=catsForState().find(c=>c.id===id),v=state.cats[id];const rows=state.history.filter(h=>h.event&&D.events.find(e=>e.id===h.event).catIds.includes(id));modal(`${c.name} · ${c.tag}`,`${portrait(c)}<p class="body">${c.memory}</p><p>故事主题：${c.theme}</p><p class="tiny">健康 ${v.health} · 信任 ${v.trust} · 压力 ${v.stress}</p><h3>成长相册 · ${galleryKeys(c).length}/3</h3><div class="cat-gallery">${['base','growth','special'].map((kind,i)=>galleryKeys(c).includes(kind)?`<figure>${galleryMedia(c,kind)}<figcaption>${kind==='base'?'初遇':kind==='growth'?'熟悉':'特别时刻'}</figcaption></figure>`:`<figure class="gallery-locked"><span>?</span><figcaption>${kind==='base'?'初遇':kind==='growth'?'熟悉':'特别时刻'} · 未解锁</figcaption></figure>`).join('')}</div><p class="tiny">信任 ≥ 50 或健康 ≥ 70，可解锁成长图；隐藏路线会解锁特别图。</p><h3>与你有关的记录</h3>${historyHtml(rows)||'<p>还没有照护记录。今天可以从读一封信开始。</p>'}`, '<button class="primary" data-action="close">收好档案</button>');}
function impactCards(actual){const r=Object.entries(actual.resources).filter(([,v])=>v);const c=Object.entries(actual.changes).flatMap(([id,vals])=>Object.entries(vals).filter(([,v])=>v).map(([k,v])=>({name:catsForState().find(x=>x.id===id).name,label:labels[k],v})));return `<div class="impact-grid">${r.map(([k,v])=>`<div class="impact-card ${v>0?'good':'cost'}"><small>${D.resourceLabels[k]}</small><b>${v>0?'+'+v:v}</b><span>当前 ${state.resources[k]}</span></div>`).join('')}${c.map(x=>`<div class="impact-card ${x.v>0?'good':'cost'}"><small>${x.name} · ${x.label}</small><b>${x.v>0?'+'+x.v:x.v}</b><span>已写入状态</span></div>`).join('')}</div>`;}
function goalBanner(goal){const old=document.querySelector('.goal-banner');if(old)old.remove();const el=document.createElement('div');el.className='goal-banner';el.innerHTML=`<span>✓</span><div><small>今日小目标完成</small><b>${goal.text}</b></div>`;document.body.append(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),300)},3000);}
function achievementBanner(list){if(!list.length)return;const old=document.querySelector('.achievement-banner');if(old)old.remove();const el=document.createElement('div');el.className='achievement-banner';el.setAttribute('role','status');el.setAttribute('aria-live','assertive');el.innerHTML=`<div class="achievement-banner-inner"><span class="achievement-burst">✦</span><div><small>成就达成</small>${list.map(a=>`<b>${a.icon} ${a.name}</b><em>${a.desc}</em>`).join('')}</div></div>`;document.body.append(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),400)},4200);}
function act(oid){try{if(musicOn)startMusic();const before=state,oldA=E.achievements(before).filter(a=>a.unlocked).map(a=>a.id),oldGoal=dailyGoal();state=E.choose(state,selected,oid);rememberProgress();const newGoal=dailyGoal();if(!oldGoal.done&&newGoal.done)sound('goal');else sound('choice');const h=state.history.at(-1),newly=E.achievements(state).filter(a=>a.unlocked&&!oldA.includes(a.id));const actual={resources:Object.fromEntries(Object.keys(h.resources).map(k=>[k,state.resources[k]-before.resources[k]])),changes:Object.fromEntries(Object.entries(h.changes).map(([id,r])=>[id,Object.fromEntries(Object.keys(r).map(k=>[k,state.cats[id][k]-before.cats[id][k]]))]))};flash=actual;save();render();lastAction={h,actual};if(newly.length)achievementBanner(newly);if(!oldGoal.done&&newGoal.done)goalBanner(newGoal);modal(newly.length?'成就达成！':'选择之后',`${newly.length?`<div class="achievement-unlock">${newly.map(a=>`<b>${a.icon} ${a.name}</b><small>${a.desc}</small>`).join('')}</div>`:''}<span class="stamp">第 ${h.day} 天 · ${h.title}</span><div class="impact-title">你的选择已经改变了：</div>${impactCards(actual)}<p class="body">${esc(h.feedback)}</p><p class="tiny">这些变化会影响后续事件的可用性、猫咪的反应和交接记录。不是装饰数值。</p><div class="ai-callout"><b>想听听居民会怎么说？</b><br><small>AI 只生成语气，不写入规则状态。</small></div>`,'<button class="ghost" data-action="ai">生成居民反馈</button><button class="primary" data-action="close">把这一页记下来</button>');setTimeout(()=>{flash={};render();},1800);}catch(err){toast(err.message);}}
function night(){const pending=E.available(state);modal(state.day===7?'给第八天的人':'结束今天的照护',`<p class="body">${pending.length?'还有 '+pending.length+' 件来信未处理：'+pending.map(e=>e.title).join('、')+'。结束今天后不会补发这些事件，未完成事项将记录在交接本。':'今天的来信都已处理。你留下了选择，也留下了它们的回声。'}</p><p class="tiny">${state.day===7?'结局依据已完成的选择计算。':'明日行动点 '+(state.resources.volunteer>=65?4:3)+'；其他资源保留。'}</p>`,'<button class="ghost" data-action="close">再看看</button><button class="primary" data-action="advance">确认交接</button>');}
function keyChoices(){return state.history.filter(h=>h.event).slice(0,5).map(h=>`<div class="choice-chip"><span>第 ${h.day} 天</span><b>${esc(h.label)}</b></div>`).join('')}
function renderEnd(){const x=E.endings(state),ach=viewedAchievements().filter(a=>a.unlocked),processed=state.history.filter(h=>h.event).length,highlight=catsForState().sort((a,b)=>state.cats[b.id].trust-state.cats[a.id].trust)[0];const routeBadge=state.variant==='pku'?(state.flags.includes('archiveLegacy')?'📚 燕园档案线':state.flags.includes('atlasGraduate')?'🎓 毕业照路线':state.flags.includes('atlasRecord')?'▤ 猫卡记录线':'🐾 初到燕园'):'';const shareText=`我在《猫城来信》${state.variant==='pku'?'燕园猫协版':''}第 ${state.week} 周照顾了 ${processed} 个事件，${ach.length} 个成就。${routeBadge} 结局：${x.title}。你会怎么选？`; $('#app').innerHTML=`<div class="shell"><header class="mast"><div class="brand"><div class="seal">🐾</div><div><h1>猫城来信</h1><div class="subtitle">一周照护周报 · 可截图分享</div></div></div><div class="daybox"><button class="music-toggle" data-action="music">${musicOn?'♫ BGM':'♪ 静音'}</button><b>WEEK ${state.week} · SUMMARY</b><span>本周交接完成</span></div></header><main class="weekly-report"><div class="report-kicker">${state.variant==='pku'?'燕园猫协 · 猫咪档案周报':'猫城救助站'} · 第 ${state.week} 周</div><h2>${x.title}</h2><p class="report-quote">“${x.summary}”</p><div class="report-stats"><div><b>${processed}</b><small>处理节点</small></div><div><b>${ach.length}</b><small>累计成就</small></div><div><b>${state.resources.materials}</b><small>救助材料</small></div><div><b>${state.resources.community}</b><small>社区信任</small></div></div><div class="report-highlight">${portrait(highlight)}<div><small>本周关系推进最明显</small><h3>${highlight.name} · ${growth(highlight,state.cats[highlight.id])[0]}</h3><p>信任 ${state.cats[highlight.id].trust} · 健康 ${state.cats[highlight.id].health} · 压力 ${state.cats[highlight.id].stress}</p></div></div><div class="report-achievements"><b>本周留下的印章</b><div>${ach.slice(-4).map(a=>`<span>${a.icon} ${a.name}</span>`).join('')||'<span>继续做出选择，第一枚印章会出现。</span>'}</div></div><div class="share-quote">${shareText}</div><div class="route-stamp">${routeBadge||'🐾 继续留下你的第一枚印章'}</div><div class="ending-grid">${catsForState().map(c=>{const o=x.outcomes[c.id]||[`${c.name}刚进入图鉴`,`新的相遇还在观察期，继续一周可以为它建立完整交接。`,`open`];const letter=C.letters[c.id]?.[o[2]]||`${c.name}把新的气味留在了地图上。下一周，请继续观察它愿不愿意留下。`;return `<article class="ending">${portrait(c)}<span class="stamp">${c.name} · ${o[2]==='warm'?'照护已有进展':o[2]==='pending'?'需要继续求助':'仍需跟进'}</span><h3>${o[0]}</h3><p>${o[1]}</p><details class="cat-letter"><summary>拆开${c.name}的信</summary><p>${letter}</p></details><button class="ghost" data-cat="${c.id}">查看选择记录</button></article>`;}).join('')}</div><div class="notice">这张周报可以截图分享。继续下一周会保留收藏和资源，并开启新的交接故事。</div><div class="bottom"><button class="ghost" data-action="journal">完整手记</button><button class="primary" data-action="share-summary">分享这张周报</button><button class="primary" data-action="continue">继续下一周</button><button class="ghost" data-action="reset">重新开始</button></div></main></div>`;window.__shareText=shareText;}
function exportJournal(){const x=E.endings(state);const lines=['猫城来信 · 七日手记','本地游戏记录；故事为虚构。',...state.history.map(h=>h.type==='week'?`第 ${h.to} 周开始，救助材料：${h.materials}`:h.type==='night'?`第 ${h.day} 天交接，未处理：${h.skipped.join('、')||'无'}`:`第 ${h.day} 天 ${h.title}\n选择：${h.label}\n${h.feedback}\n${delta(h.resources)}\n${changes(h)}`),...D.cats.map(c=>`${c.name}：${x.outcomes[c.id][0]}\n${x.outcomes[c.id][1]}`)];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\n\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='猫城来信-我的七日手记.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function ai(){const d=document.querySelector('dialog');if(!d||!lastAction)return;const box=document.createElement('div');box.className='ai-result';box.textContent='居民反馈生成中…';d.querySelector('.modal-card').insertBefore(box,d.querySelector('.dialog-actions'));try{const endpoint=window.CATCITY_AI_ENDPOINT;if(endpoint){const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event:lastAction.h.title,choice:lastAction.h.label,feedback:lastAction.h.feedback})});if(!r.ok)throw Error('AI endpoint');const j=await r.json();box.textContent='AI 居民反馈：'+String(j.text||j.feedback||'').slice(0,120);}else{const h=lastAction.h;box.textContent='AI 居民反馈（本地备用）：“我听见你这次选择里的犹豫了。请把记录留下，明天我们继续看它需要什么。”';}}catch{box.textContent='AI 接口暂不可用，已使用备用反馈：居民会记住这次选择，也会继续观察后续照护。';}}
async function shareGame(){const url=location.href.split('?')[0]+'?fresh=1&v=mobile';const data={title:'猫城来信',text:'来玩一局《猫城来信》：照顾六只猫，发现隐藏路线。',url};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(url);toast('试玩链接已复制，可以发给朋友');}}catch(e){if(e.name!=='AbortError')toast('分享失败，请复制地址栏链接');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
const tutorialSlides=[['1 · 先看地图','地图上的地点是校园里的照护现场。带“新”标记的小猫，代表今天在那里出现了一封来信。点击小猫，直接走到它身边。','地图上的新标记 = 今日可触发剧情'],['2 · 再读档案','右侧“六个名字”可以打开猫咪档案。健康、信任、压力不是分数榜，而是提示你下一步该靠近、等待，还是先补充资源。','先了解一只猫，再决定怎么做'],['3 · 做一个选择','事件卡里的每个选项都会显示资源代价。点击“查看取舍”可以预览影响；做出选择后，资源数字会闪动，结果卡会列出实际变化。','选择不会只改变文字，会写入后续状态'],['4 · 把今天交接下去','处理完想看的来信后，点击“结束今天”。未处理的来信会进入交接本，第七天会看到六只猫各自的阶段性去向。','救助没有通关画面，只有下一次照护']];
function tutorial(step=0){const old=document.querySelector('.tutorial-dialog');if(old)old.remove();const d=document.createElement('dialog');d.className='tutorial-dialog reading';const x=tutorialSlides[step];d.innerHTML=`<div class="modal-card tutorial-card"><span class="stamp">新手关 · ${step+1} / ${tutorialSlides.length}</span><h2>${x[0]}</h2><p class="body">${x[1]}</p><div class="tutorial-tip">🐾 ${x[2]}</div><div class="dialog-actions"><button class="ghost" data-action="tutorial-skip">跳过指引</button><button class="primary" data-action="tutorial-next">${step===tutorialSlides.length-1?'开始照护':'下一步'}</button></div></div>`;d.dataset.step=step;document.body.append(d);d.showModal();}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.event){selected=b.dataset.event;render();return;}if(b.dataset.cat){showCat(b.dataset.cat);return;}if(b.dataset.option){act(b.dataset.option);return;}switch(b.dataset.action){case 'begin':{const variant=b.dataset.variant||'default';activeMetaKey=variant==='pku'?'catcity-meta-pku-v1':'catcity-meta';meta=loadMeta();meta.gallery=Array.isArray(meta.gallery)?meta.gallery:[];state=E.initial('normal',b.dataset.boon||'steady',variant);if(musicOn)startMusic();save();render();break;}case 'demo':state=E.initial('demo','steady',b.dataset.variant||'pku');save();render();break;case 'close':b.closest('dialog').close();break;case 'tutorial':tutorial(0);break;case 'codex':codex();break;case 'share':shareGame();break;case 'music':toggleMusic();break;case 'share-summary':navigator.share?navigator.share({title:'猫城来信周报',text:window.__shareText,url:location.href}):navigator.clipboard?.writeText(window.__shareText).then(()=>toast('周报文案已复制，可以发给朋友'));break;case 'tutorial-next':{const d=b.closest('dialog'),n=Number(d.dataset.step)+1;if(n>=tutorialSlides.length){localStorage.setItem('catcity-tutorial','1');d.close();}else{d.close();tutorial(n);}break;}case 'tutorial-skip':localStorage.setItem('catcity-tutorial','1');b.closest('dialog').close();break;case 'ai':ai();break;case 'night':night();break;case 'advance':b.closest('dialog').close();state=E.advance(state);save();selected=null;render();break;case 'continue':state=E.continueWeek(state);save();selected=null;render();break;case 'journal':modal('七日交接本',historyHtml(state.history)||'<p>还没有记录。</p>','<button class="primary" data-action="close">合上手记</button>');break;case 'reset':modal('开始新的一周','<p>重新开始将覆盖这个浏览器里的试玩进度。</p>','<button class="ghost" data-action="close">保留进度</button><button class="primary" data-action="restart">重新开始</button>');break;case 'restart':b.closest('dialog').close();state=E.initial();selected=null;save();render();break;case 'export':exportJournal();break;}});
const fresh=new URLSearchParams(location.search).has('fresh');if(fresh){try{localStorage.removeItem('catcity-save')}catch{}}state=fresh?null:load();if(state?.variant==='pku'){activeMetaKey='catcity-meta-pku-v1';meta=loadMeta();meta.gallery=Array.isArray(meta.gallery)?meta.gallery:[];}render();setTimeout(()=>{if(state&&!localStorage.getItem('catcity-tutorial'))tutorial(0);},250);
})();


